### `src/app.ts`

```ts
import Fastify from "fastify";
import { serializerCompiler, validatorCompiler, type ZodTypeProvider } from "fastify-type-provider-zod";
import type { Pool } from "pg";
import type { Config } from "./config.js";
import { bearerAuth } from "./http/auth.js";
import { registerErrorHandler } from "./http/errors.js";
import { booksRoutes } from "./modules/books/routes.js";
import { authorsRoutes } from "./modules/authors/routes.js";
import { stockRoutes } from "./modules/stock/routes.js";

export function buildApp({ config, pool }: { config: Config; pool: Pool }) {
  const app = Fastify({
    logger: config.NODE_ENV === "test" ? false : { level: config.LOG_LEVEL, redact: ["req.headers.authorization"] },
    bodyLimit: 100_000,
  }).withTypeProvider<ZodTypeProvider>();

  app.setValidatorCompiler(validatorCompiler);
  app.setSerializerCompiler(serializerCompiler);
  registerErrorHandler(app);

  // liveness+readiness in one: it proves the DB is reachable
  app.get("/healthz", async () => { await pool.query("SELECT 1"); return { status: "ok" }; });

  app.register(async (api) => {
    api.addHook("onRequest", bearerAuth(config.API_TOKEN));
    api.register(authorsRoutes, { pool });
    api.register(booksRoutes, { pool });
    api.register(stockRoutes, { pool });
  }, { prefix: "/v1" });

  return app;
}
```

### `src/http/auth.ts`

```ts
import { timingSafeEqual, createHash } from "node:crypto";
import type { FastifyRequest } from "fastify";

const digest = (s: string) => createHash("sha256").update(s).digest(); // equal length for timingSafeEqual

export const bearerAuth = (token: string) => {
  const expected = digest(token);
  return async (req: FastifyRequest) => {
    const given = (req.headers.authorization ?? "").replace(/^Bearer /, "");
    if (!timingSafeEqual(digest(given), expected)) {
      throw Object.assign(new Error("Unauthorized"), { statusCode: 401 });
    }
  };
};
```

### `src/http/errors.ts`

```ts
import type { FastifyInstance } from "fastify";
import { hasZodFastifySchemaValidationErrors } from "fastify-type-provider-zod";

const PG: Record<string, [number, string]> = {
  "23505": [409, "Resource already exists"],          // unique_violation (ISBN)
  "23503": [422, "Referenced resource does not exist"], // foreign_key_violation (author)
  "23514": [409, "Operation violates a constraint"],    // check_violation (stock < 0)
};

export function registerErrorHandler(app: FastifyInstance) {
  app.setErrorHandler((err: any, req, reply) => {
    let status = 500, title = "Internal Server Error", extra = {};
    if (hasZodFastifySchemaValidationErrors(err)) { status = 400; title = "Validation failed"; extra = { errors: err.validation }; }
    else if (PG[err.code]) [status, title] = PG[err.code]!;
    else if (err.statusCode && err.statusCode < 500) { status = err.statusCode; title = err.message; }
    if (status >= 500) req.log.error({ err }, "unhandled error");   // never leak details on 5xx
    reply.code(status).type("application/problem+json").send({ type: "about:blank", title, status, ...extra });
  });
  app.setNotFoundHandler((_req, reply) =>
    reply.code(404).type("application/problem+json").send({ type: "about:blank", title: "Not Found", status: 404 }));
}
```

### First slice: books with authors and initial stock

`src/modules/books/schemas.ts`

```ts
import { z } from "zod";

export const Isbn = z.string().regex(/^\d{13}$/, "ISBN-13, digits only");
export const CreateBook = z.object({
  isbn: Isbn,
  title: z.string().trim().min(1).max(300),
  priceCents: z.number().int().min(0).max(10_000_00),
  authorIds: z.array(z.uuid()).min(1).max(10),
  initialStock: z.number().int().min(0).default(0),
});
export const Book = z.object({
  id: z.uuid(), isbn: Isbn, title: z.string(), priceCents: z.number().int(),
  authors: z.array(z.object({ id: z.uuid(), name: z.string() })),
  stock: z.number().int(),
  createdAt: z.date(),
});
export const IdParam = z.object({ id: z.uuid() });
```

`src/modules/books/repo.ts`

```ts
import type { Pool } from "pg";

const SELECT_BOOK = `
  SELECT b.id, b.isbn, b.title, b.price_cents AS "priceCents", b.created_at AS "createdAt",
         s.quantity AS stock,
         COALESCE(json_agg(json_build_object('id', a.id, 'name', a.name) ORDER BY a.name)
                  FILTER (WHERE a.id IS NOT NULL), '[]') AS authors
  FROM books b
  JOIN book_stock s ON s.book_id = b.id
  LEFT JOIN book_authors ba ON ba.book_id = b.id
  LEFT JOIN authors a ON a.id = ba.author_id`;

export const booksRepo = (pool: Pool) => ({
  async create(i: { isbn: string; title: string; priceCents: number; authorIds: string[]; initialStock: number }) {
    const c = await pool.connect();
    try {
      await c.query("BEGIN");
      const { rows: [{ id }] } = await c.query(
        "INSERT INTO books (isbn, title, price_cents) VALUES ($1,$2,$3) RETURNING id",
        [i.isbn, i.title, i.priceCents]);
      await c.query(
        "INSERT INTO book_authors (book_id, author_id) SELECT $1, unnest($2::uuid[])", [id, i.authorIds]);
      await c.query("INSERT INTO book_stock (book_id, quantity) VALUES ($1,$2)", [id, i.initialStock]);
      await c.query("COMMIT");
      return id as string;
    } catch (e) { await c.query("ROLLBACK"); throw e; }
    finally { c.release(); }
  },

  async get(id: string) {
    const { rows } = await pool.query(`${SELECT_BOOK} WHERE b.id = $1 GROUP BY b.id, s.quantity`, [id]);
    return rows[0] ?? null;
  },

  async list({ after, limit }: { after?: string; limit: number }) {
    const { rows } = await pool.query(
      `${SELECT_BOOK} WHERE ($1::uuid IS NULL OR b.id > $1) GROUP BY b.id, s.quantity ORDER BY b.id LIMIT $2`,
      [after ?? null, limit]);
    return rows;
  },
});
```

`src/modules/books/routes.ts`

```ts
import type { FastifyPluginAsyncZod } from "fastify-type-provider-zod";
import type { Pool } from "pg";
import { z } from "zod";
import { Book, CreateBook, IdParam } from "./schemas.js";
import { booksRepo } from "./repo.js";

export const booksRoutes: FastifyPluginAsyncZod<{ pool: Pool }> = async (app, { pool }) => {
  const repo = booksRepo(pool);

  app.post("/books", { schema: { body: CreateBook, response: { 201: Book } } }, async (req, reply) => {
    const id = await repo.create(req.body);
    return reply.code(201).header("location", `/v1/books/${id}`).send((await repo.get(id))!);
  });

  app.get("/books/:id", { schema: { params: IdParam, response: { 200: Book } } }, async (req, reply) => {
    const book = await repo.get(req.params.id);
    return book ?? reply.callNotFound();
  });

  app.get("/books", {
    schema: {
      querystring: z.object({ after: z.uuid().optional(), limit: z.coerce.number().int().min(1).max(100).default(50) }),
      response: { 200: z.object({ items: z.array(Book), next: z.uuid().nullable() }) },
    },
  }, async (req) => {
    const items = await repo.list(req.query);
    return { items, next: items.length === req.query.limit ? items.at(-1)!.id : null };
  });
};
```

Authors follow the same pattern: `POST /authors`, `GET /authors/:id` and `GET /authors`. Deleting an author is `RESTRICT`, which surfaces as a 409 while the author still has books.

### Stock adjustment (the part that must be correct)

This is a single atomic statement. `PATCH`-style "set quantity to N" is intentionally not offered, because two staff members would overwrite each other. The API accepts deltas only.

`src/modules/stock/repo.ts`

```ts
export const stockRepo = (pool: Pool) => ({
  // returns new quantity, or null if the book doesn't exist.
  // Going below zero raises 23514 → 409 via the error handler.
  async adjust(bookId: string, delta: number, reason: string) {
    const { rows } = await pool.query(
      `WITH upd AS (
         UPDATE book_stock SET quantity = quantity + $2, updated_at = now()
         WHERE book_id = $1 RETURNING quantity)
       INSERT INTO stock_movements (book_id, delta, reason, resulting_quantity)
       SELECT $1, $2, $3, quantity FROM upd
       RETURNING resulting_quantity AS quantity`,
      [bookId, delta, reason]);
    return rows[0]?.quantity ?? null;
  },
});
```

Route: `POST /v1/books/:id/stock-adjustments` with body `{ delta: int ≠ 0, reason: string }`, returning `200 { quantity }`, or 404 or 409. The first slice includes this endpoint, since stock is the point of the system.

### `src/server.ts` (graceful shutdown)

```ts
import pg from "pg";
import { buildApp } from "./app.js";
import { loadConfig } from "./config.js";

const config = loadConfig();
const pool = new pg.Pool({ connectionString: config.DATABASE_URL, max: 10, statement_timeout: 5000 });
const app = buildApp({ config, pool });

for (const sig of ["SIGTERM", "SIGINT"] as const) {
  process.once(sig, async () => {
    try { await app.close(); await pool.end(); process.exit(0); }   // drain in-flight requests, then the pool
    catch (e) { app.log.error(e); process.exit(1); }
  });
}
await app.listen({ host: "0.0.0.0", port: config.PORT });
```

### Test (`test/books.test.ts`, the stock invariant)

```ts
it("never lets stock go negative, even under concurrency", async () => {
  const book = await createBook({ initialStock: 5 });
  const results = await Promise.all(
    Array.from({ length: 10 }, () =>
      app.inject({ method: "POST", url: `/v1/books/${book.id}/stock-adjustments`,
        headers: auth, payload: { delta: -1, reason: "sale" } })));
  expect(results.filter(r => r.statusCode === 200)).toHaveLength(5);
  expect(results.filter(r => r.statusCode === 409)).toHaveLength(5);
  expect((await getBook(book.id)).stock).toBe(0);
});
```

Also covered in the first slice: 401 without a token, 400 on a bad ISBN, 409 on a duplicate ISBN, 422 on an unknown author, and the 404 for a missing book.

### Supporting files

`compose.yaml`: `postgres:18` with a healthcheck and a named volume. `.env.example` has `DATABASE_URL`, `API_TOKEN` and `PORT`.

`.github/workflows/ci.yml`: Postgres 18 service container, then `npm ci`, `npm run migrate`, and `npm run check`.

`Dockerfile`: a build stage runs `npm ci && npm run build`. The runtime stage is `node:24-slim`, uses `npm ci --omit=dev`, copies `dist/` and `migrations/`, runs as the `node` user, and ends with `CMD ["node","dist/server.js"]`.

## 5. Build order

1. **Scaffold (about half a day):** tooling, config, `/healthz`, CI green, empty migration run.
2. **Slice 1:** the migration above, `POST/GET /books`, `POST /authors`, auth, the error handler and tests. It runs end to end through HTTP, SQL and the constraints.
3. **Slice 2:** stock adjustments with the concurrency test, then `GET /books` pagination and filtering (`?authorId=`, `?isbn=`).
4. **Later, when asked for:** `PATCH`/`DELETE` for books and authors, a movement-history endpoint (`GET /books/:id/stock-movements`) and OpenAPI docs via `@fastify/swagger`.

## 6. Assumptions to confirm

- Hosting is unspecified. The Dockerfile keeps it portable, and migrations should run as a pre-deploy step with a backup before the first production migration.
- If a book can exist in several editions or formats, the schema needs an `editions` level. I assumed one ISBN equals one book.
- Bearer-token auth is a placeholder. If the API will be reachable from outside a private network, say so and I'd add per-client keys or OIDC before anything else.
